// Contrato C3 2.3: el cuerpo trae solo el id de la alerta. Un id que no es UUID
// no puede existir, asi que recibe el mismo 404 que una alerta ajena: el
// contrato pide no distinguir entre "no existe" y "es de otro ciudadano".
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const cuerpo = $('Webhook Descartar Alerta').first().json.body || {};
const id = String(cuerpo.id || '');

if (!UUID.test(id)) {
  return [{ json: { valido: false, http_code: 404, cuerpo: { error: 'alerta_no_encontrada' } } }];
}

return [{ json: { valido: true, alerta_id: id } }];

// Contrato C3 2.3: 200 { ok: true } si el UPDATE alcanzo la alerta del
// ciudadano del token; 404 alerta_no_encontrada si no existe o es de otro.
const filas = $input.all()
  .map((i) => i.json)
  .filter((f) => f && f.id);

if (filas.length === 0) {
  return [{ json: { http_code: 404, cuerpo: { error: 'alerta_no_encontrada' } } }];
}

return [{ json: { http_code: 200, cuerpo: { ok: true } } }];

