const cuerpo = $('Webhook Guardar Ubicacion').first().json.body || {};
const lat = Number(cuerpo.lat);
const lng = Number(cuerpo.lng);
const numero = (v) => typeof v === 'number' && Number.isFinite(v);

if (
  cuerpo.lat === undefined || cuerpo.lat === null || cuerpo.lat === ''
  || cuerpo.lng === undefined || cuerpo.lng === null || cuerpo.lng === ''
  || !numero(lat) || !numero(lng)
  || lat < -90 || lat > 90
  || lng < -180 || lng > 180
) {
